            NavigationBar(containerColor = MaterialTheme.colorScheme.background) {
                NavigationBarItem(
                    icon = { Icon(Icons.Filled.SportsMartialArts, contentDescription = null) },
                    label = { Text("Match") },
                    selected = selectedTab == HomeTab.MATCH,
